// features/auth.feature: Signing out clears the session cookie.
// Signing in needs the real session cookie, so this test signs in with USERS/PASSWORD
// (the PW-4 exception for sign-in tests, as in api/auth.spec.ts).
import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
  // Arrange: sign in as the seeded member; the request context keeps the session cookie.
  await expectStatus(
    await request.post("/api/auth/login", { data: { email: USERS.member, password: PASSWORD } }),
    200,
  );
  const before = await request.storageState();
  expect(before.cookies.map((c) => c.name), "signed in with a session cookie").toContain("session");

  // Act
  const response = await request.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const cleared = response
    .headersArray()
    .find((h) => h.name.toLowerCase() === "set-cookie" && /^session=/.test(h.value));
  expect(cleared?.value, "logout sends a Set-Cookie for session").toBeDefined();
  expect(cleared?.value).toMatch(/^session=(""|);/);
  expect(cleared?.value.toLowerCase()).toContain("max-age=0");
  const after = await request.storageState();
  expect(after.cookies.map((c) => c.name), "session cookie no longer stored").not.toContain("session");
});
